create table clusters(id bigint generated by default as identity primary key,name text not null,sort int default 0);
create table products(id bigint generated by default as identity primary key,cluster_id bigint references clusters on delete cascade,name text not null,description text,image text,active boolean default true);
create table variants(id bigint generated by default as identity primary key,product_id bigint references products on delete cascade,model text,size text,color text,price int not null,stock int default 0,active boolean default true);
create table orders(id bigint generated by default as identity primary key,created_at timestamptz default now(),name text,phone text,items jsonb,total int,status text default 'menunggu',proof text);
alter table clusters enable row level security;
alter table products enable row level security;
alter table variants enable row level security;
alter table orders enable row level security;
